106	// TestBatchRejectsCyclesAfterReplacement verifies that a final graph with a
107	// self-dependency or an indirect cycle is rejected, and that the rejection
108	// names the datasets involved.
109	func TestBatchRejectsCyclesAfterReplacement(t *testing.T) {
110		t.Run("self dependency", func(t *testing.T) {
111			graph := buildGraph(t, P("A"))
112			plan := planOf(change("A", "A"))
113			_, err := PreviewBatch(graph, plan)
114			if !errors.Is(err, ErrCycle) {
115				t.Fatalf("err = %v, want ErrCycle", err)
116			}
117			if !strings.Contains(err.Error(), "A") {
118				t.Errorf("error %q does not name dataset A", err)
119			}
120		})
