202	// TestBatchEmptyPlanAndIdempotentReApply verifies that an empty plan and a
203	// repeated application of the same plan both succeed with empty change and
204	// impact lists.
205	func TestBatchEmptyPlanAndIdempotentReApply(t *testing.T) {
206		graph := buildGraph(t, P("A"), P("B", "A"), P("C", "B"))
207		plan := planOf(change("B", "A")) // identical to current state
208	
209		report, err := PreviewBatch(graph, plan)
