482	// TestBatchDeterministicOutput verifies that the same current graph and plan
483	// produce byte-identical success output even when records and upstreams are in
484	// a different order.
485	func TestBatchDeterministicOutput(t *testing.T) {
486		build := func() map[string]*Lineage {
487			return buildGraph(t, P("A"), P("B", "A"), P("C", "B"))
488		}
489		// Plan 1: shuffled order, shuffled upstreams with duplicates.
490		plan1 := planOf(
491			change("D", "C"),
492			change("B"),
493			change("C", "A", "A"),
494		)
495		// Plan 2: different record order, different upstream order, no duplicates.
496		plan2 := planOf(
497			change("C", "A"),
498			change("D", "C"),
499			change("B"),
500		)
501	
502		g1 := build()
503		r1, err := ApplyBatch(g1, plan1)
504		if err != nil {
505			t.Fatalf("ApplyBatch plan1 unexpected error: %v", err)
506		}
507		g2 := build()
508		r2, err := ApplyBatch(g2, plan2)
509		if err != nil {
510			t.Fatalf("ApplyBatch plan2 unexpected error: %v", err)
511		}
512	
513		b1, err := MarshalGraphFile(g1)
514		if err != nil {
515			t.Fatalf("MarshalGraphFile g1 unexpected error: %v", err)
516		}
517		b2, err := MarshalGraphFile(g2)
518		if err != nil {
519			t.Fatalf("MarshalGraphFile g2 unexpected error: %v", err)
520		}
521		if string(b1) != string(b2) {
522			t.Fatalf("graph bytes differ:\n--- plan1 ---\n%s\n--- plan2 ---\n%s", b1, b2)
523		}
524	
525		// Reports must also be identical.
526		rb1, err := json.Marshal(r1)
527		if err != nil {
528			t.Fatalf("json.Marshal r1 unexpected error: %v", err)
529		}
530		rb2, err := json.Marshal(r2)
531		if err != nil {
532			t.Fatalf("json.Marshal r2 unexpected error: %v", err)
533		}
534		if string(rb1) != string(rb2) {
535			t.Fatalf("report bytes differ:\n--- plan1 ---\n%s\n--- plan2 ---\n%s", rb1, rb2)
536		}
537	}
538	
539	// TestBatchPreviewApplyConsistency verifies that preview and apply produce the
540	// same report for the same current graph and plan.
541	func TestBatchPreviewApplyConsistency(t *testing.T) {
542		graph := buildGraph(t, P("A"), P("B", "A"), P("C", "B"))
543		plan := planOf(change("B"), change("C", "A"))
544	
545		preview, err := PreviewBatch(graph, plan)
546		if err != nil {
547			t.Fatalf("PreviewBatch unexpected error: %v", err)
548		}
549		applied, err := ApplyBatch(graph, plan)
550		if err != nil {
551			t.Fatalf("ApplyBatch unexpected error: %v", err)
552		}
553		if !reflect.DeepEqual(preview, applied) {
554			t.Fatalf("preview and apply reports differ:\n preview=%#v\n applied=%#v", preview, applied)
555		}
556	}
557	
558	// TestBatchJSONRoundTrip verifies that a graph marshaled to JSON and parsed
559	// back is equivalent, and that empty lists encode as [].
560	func TestBatchJSONRoundTrip(t *testing.T) {
561		graph := buildGraph(t, P("A"), P("B", "A"))
562		data, err := MarshalGraphFile(graph)
563		if err != nil {
564			t.Fatalf("MarshalGraphFile unexpected error: %v", err)
565		}
566		parsed, err := UnmarshalGraphFile(data)
567		if err != nil {
568			t.Fatalf("UnmarshalGraphFile unexpected error: %v", err)
569		}
570		if !reflect.DeepEqual(parsed, graph) {
571			t.Fatalf("round-trip mismatch:\n got %#v\nwant %#v", parsed, graph)
572		}
573	
574		// Empty graph encodes datasets as [].
575		empty := map[string]*Lineage{}
576		data, err = MarshalGraphFile(empty)
577		if err != nil {
578			t.Fatalf("MarshalGraphFile empty unexpected error: %v", err)
579		}
580		if !strings.Contains(string(data), `"datasets": []`) {
581			t.Errorf("empty graph JSON = %s, want datasets: []", data)
582		}
583	}
584	
585	// TestBatchUnmarshalRejectsInvalidGraphJSON verifies that UnmarshalGraphFile
586	// rejects structurally invalid graphs.
587	func TestBatchUnmarshalRejectsInvalidGraphJSON(t *testing.T) {
588		cases := map[string]string{
589			"empty name":      `{"datasets":[{"name":"","upstreams":[]}]}`,
590			"duplicate":       `{"datasets":[{"name":"A","upstreams":[]},{"name":"A","upstreams":[]}]}`,
591			"missing upstream": `{"datasets":[{"name":"A","upstreams":["ghost"]}]}`,
592			"cycle":           `{"datasets":[{"name":"A","upstreams":["B"]},{"name":"B","upstreams":["A"]}]}`,
593			"invalid json":    `{not json`,
594		}
595		for name, data := range cases {
596			t.Run(name, func(t *testing.T) {
597				_, err := UnmarshalGraphFile([]byte(data))
598				if err == nil {
599					t.Fatalf("expected error for %s, got nil", name)
600				}
601			})
602		}
603	}
604	
605	// TestUnmarshalPlanRejectsDuplicateFields: a known field declared twice within
606	// the same object makes the whole plan ambiguous and must be rejected, even
607	// when the duplicates carry identical values, one is null, or the surviving
608	// value is a legal empty list. Field names are recognized after JSON
609	// unescaping and with the decoder's Unicode case folding, so escaped or
610	// fold-equivalent spellings of a second declaration still collide.
611	func TestUnmarshalPlanRejectsDuplicateFields(t *testing.T) {
612		const (
613			longS       = "ſ" // U+017F LATIN SMALL LETTER LONG S, folds to ASCII "s"
614			longSEscape = "\\" + "u017f"
615		)
616	
617		cases := map[string]struct {
618			data     string
619			field    string
620			location string
621		}{
622			"changes twice identical": {
623				`{"changes":[{"name":"A","upstreams":[]}],"changes":[{"name":"A","upstreams":[]}]}`,
624				"changes", "top level",
625			},
626			"real changes then empty replacement": {
627				`{"changes":[{"name":"A","upstreams":[]}],"changes":[]}`,
628				"changes", "top level",
629			},
630			"null changes then real": {
631				`{"changes":null,"changes":[{"name":"A","upstreams":[]}]}`,
632				"changes", "top level",
633			},
634			"removals twice": {
635				`{"removals":["A"],"removals":["B"]}`,
636				"removals", "top level",
637			},
638			"removals then empty replacement": {
639				`{"removals":["A"],"removals":[]}`,
640				"removals", "top level",
641			},
642			"null removals then real": {
643				`{"removals":null,"removals":["A"]}`,
644				"removals", "top level",
645			},
646			"name twice same value": {
647				`{"changes":[{"name":"A","name":"A","upstreams":[]}]}`,
648				"name", `index 0 of "changes"`,
649			},
650			"name twice would swap target": {
651				`{"changes":[{"name":"A","name":"B","upstreams":[]}]}`,
652				"name", `index 0 of "changes"`,
653			},
654			"null name then valid": {
655				`{"changes":[{"name":null,"name":"A","upstreams":[]}]}`,
656				"name", `index 0 of "changes"`,
657			},
658			"upstreams then empty would silently clear": {
659				`{"changes":[{"name":"A","upstreams":["B"],"upstreams":[]}]}`,
660				"upstreams", `index 0 of "changes"`,
661			},
662			"null upstreams then valid in second record": {
663				`{"changes":[{"name":"A","upstreams":[]},{"name":"B","upstreams":null,"upstreams":["A"]}]}`,
664				"upstreams", `index 1 of "changes"`,
665			},
666			"escaped name key": {
667				`{"changes":[{"name":"A","na\u006de":"A","upstreams":[]}]}`,
668				"name", `index 0 of "changes"`,
669			},
670			"case variant name": {
671				`{"changes":[{"Name":"A","name":"A","upstreams":[]}]}`,
672				"name", `index 0 of "changes"`,
673			},
674			"case variant changes": {
675				`{"Changes":[],"changes":[{"name":"A","upstreams":[]}]}`,
676				"changes", "top level",
677			},
678			"case variant removals": {
679				`{"Removals":[],"removals":["A"]}`,
680				"removals", "top level",
681			},
682			"case variant upstreams": {
683				`{"changes":[{"name":"A","UPSTREAMS":[],"upstreams":[]}]}`,
684				"upstreams", `index 0 of "changes"`,
685			},
686			"long s changes": {
687				`{"change` + longS + `":[],"changes":[{"name":"A","upstreams":[]}]}`,
688				"changes", "top level",
689			},
690			"long s upstreams via JSON escape": {
691				`{"changes":[{"name":"A","up` + longSEscape + `treams":[],"upstreams":[]}]}`,
692				"upstreams", `index 0 of "changes"`,
693			},
694			"big number in unknown field before duplicated changes": {
695				`{"note":1e400,"changes":[],"changes":[{"name":"A","upstreams":[]}]}`,
696				"changes", "top level",
697			},
698			"big number nested in record before duplicated upstreams": {
699				`{"changes":[{"name":"A","vals":{"deep":[1e999]},"upstreams":[],"upstreams":[]}]}`,
700				"upstreams", `index 0 of "changes"`,
701			},
702		}
703		for name, tc := range cases {
704			t.Run(name, func(t *testing.T) {
705				// Every "escape" case really must carry ASCII escape bytes.
706				if strings.Contains(name, "escape") && !strings.Contains(tc.data, longSEscape) && !strings.Contains(tc.data, `\u006d`) {
707					t.Fatalf("test case %q does not actually use a JSON escape", name)
708				}
709				_, err := UnmarshalPlan([]byte(tc.data))
710				if !errors.Is(err, ErrInvalidArgument) {
711					t.Fatalf("err = %v, want ErrInvalidArgument", err)
712				}
713				if !strings.Contains(err.Error(), `"`+tc.field+`"`) {
714					t.Errorf("err = %q, want it to name duplicated field %q", err, tc.field)
715				}
716				if !strings.Contains(err.Error(), tc.location) {
717					t.Errorf("err = %q, want it to locate the duplicate %q", err, tc.location)
718				}
719			})
720		}
721	}
722	
723	// TestUnmarshalPlanDuplicateTolerances: repetitions that do NOT create
724	// ambiguity stay legal — unknown fields may repeat anywhere (even holding
725	// duplicate keys or oversized numbers inside), each change record declares
726	// its own name, and duplicate names inside one upstreams array still count
727	// as one relationship. A known field written once in a case-variant or
728	// fold-equivalent spelling is still recognized.
729	func TestUnmarshalPlanDuplicateTolerances(t *testing.T) {
730		cases := map[string]string{
731			"empty plan":                        `{}`,
732			"empty changes and removals":        `{"changes":[],"removals":[]}`,
733			"removals only":                     `{"removals":["A"]}`,
734			"unknown top-level field repeats":   `{"meta":"x","meta":"y","changes":[{"name":"A","upstreams":[]}]}`,
735			"unknown record field repeats":      `{"changes":[{"name":"A","note":1,"note":2,"upstreams":[]}]}`,
736			"known keys nested inside unknown field": `{"meta":{"changes":[],"changes":[],"name":"A","upstreams":null},` +
737				`"changes":[{"name":"A","upstreams":[]}]}`,
738			"big numbers in unknown fields":          `{"note":1e400,"changes":[{"name":"A","upstreams":[],"extra":[1e999,{"z":-1e400}]}]}`,
739			"case variant spellings declared once":   `{"Changes":[{"Name":"A","Upstreams":[]}],"Removals":["B"]}`,
740			"duplicate names inside upstreams array": `{"changes":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A","A"]}]}`,
741		}
742		for name, data := range cases {
743			t.Run(name, func(t *testing.T) {
744				plan, err := UnmarshalPlan([]byte(data))
745				if err != nil {
746					t.Fatalf("UnmarshalPlan rejected a legal document: %v", err)
747				}
748				if name == "duplicate names inside upstreams array" {
749					// The duplicate upstream still counts once downstream: the
750					// plan parses, and normalization happens in computeBatch.
751					if len(plan.Changes) != 2 {
752						t.Fatalf("plan.Changes = %v, want 2 records", plan.Changes)
753					}
754				}
755			})
756		}
757	
758		// Dataset names stay case-sensitive and keep their spaces; only field
759		// names fold. Two records named " A " and "a" are distinct declarations.
760		plan, err := UnmarshalPlan([]byte(`{"changes":[{"name":" A ","upstreams":[]},{"name":"a","upstreams":[" A "]}]}`))
761		if err != nil {
762			t.Fatalf("case/space-sensitive dataset names rejected: %v", err)
763		}
764		if len(plan.Changes) != 2 || plan.Changes[0].Name != " A " || plan.Changes[1].Name != "a" {
765			t.Errorf("plan.Changes = %+v, want names %q and %q preserved verbatim", plan.Changes, " A ", "a")
766		}
767	}
