	if err != nil {
		t.Fatalf("MarshalGraphFile empty unexpected error: %v", err)
	}
	if !strings.Contains(string(data), `"datasets": []`) {
		t.Errorf("empty graph JSON = %s, want datasets: []", data)
	}
}

